using System;using System.Windows.Input;namespace MediaStudioWpf48.Commands{public class RelayCommand:ICommand{Action<object>a;Predicate<object>c;public RelayCommand(Action<object>x,Predicate<object>y=null){a=x;c=y;}public bool CanExecute(object p)=>c==null||c(p);public void Execute(object p)=>a(p);public event EventHandler CanExecuteChanged;public void Raise()=>CanExecuteChanged?.Invoke(this,EventArgs.Empty);}}